import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    current_desks = []
    desired_desks = []

    for _ in range(n):
        u = int(next(iterator))
        v = int(next(iterator))
        current_desks.append(u)
        desired_desks.append(v)

    MOD = 1000000007

    adj = {}
    for u, v in zip(current_desks, desired_desks):
        if u not in adj:
            adj[u] = []
        adj[u].append(v)

    visited = set()
    components = []

    def dfs(start_node, comp_nodes, comp_edges):
        stack = [start_node]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            comp_nodes.append(node)

            if node in adj:
                for neighbor in adj[node]:
                    comp_edges.append((node, neighbor))
                    if neighbor not in visited:
                        stack.append(neighbor)

    for u in current_desks:
        if u not in visited:
            comp_nodes = []
            comp_edges = []
            dfs(u, comp_nodes, comp_edges)
            components.append((comp_nodes, comp_edges))

    ans = 1

    for nodes, edges in components:
        num_nodes = len(nodes)
        num_edges = len(edges)

        if num_edges < num_nodes:
            ans = (ans * 0) % MOD
            break

        if num_edges > num_nodes:
            ans = (ans * 0) % MOD 
            break

        if num_edges == num_nodes:
            if num_nodes == 1:
                ans = (ans * 1) % MOD
            else:
                ans = (ans * 2) % MOD

    print(ans)

if __name__ == "__main__":
    main()
